#!/usr/bin/env node
// MIPS32r2 (little-endian, o32) interpreter for doomgeneric_mips.
// Boots Doom and saves rendered frames as BMP files to disk.
'use strict';
const fs = require('fs');
const path = require('path');

const ELF_PATH = process.env.DOOM_ELF || path.join(__dirname, 'doomgeneric_mips');
const FRAME_DIR = process.env.DOOM_FRAME_DIR || '/tmp';
const MAX_FRAMES = parseInt(process.env.DOOM_FRAMES || '5', 10); // stop after this many frames

// ---------------------------------------------------------------------------
// ELF loading
// ---------------------------------------------------------------------------
const elf = fs.readFileSync(ELF_PATH);
if (elf[0] !== 0x7f || elf[1] !== 0x45 || elf[2] !== 0x4c || elf[3] !== 0x46)
  throw new Error('not an ELF file');
const e_entry   = elf.readUInt32LE(24);
const e_phoff   = elf.readUInt32LE(28);
const e_phentsz = elf.readUInt16LE(42);
const e_phnum   = elf.readUInt16LE(44);

const PT_LOAD = 1;
let maxEnd = 0;
const loads = [];
for (let i = 0; i < e_phnum; i++) {
  const off = e_phoff + i * e_phentsz;
  const p_type   = elf.readUInt32LE(off + 0);
  const p_offset = elf.readUInt32LE(off + 4);
  const p_vaddr  = elf.readUInt32LE(off + 8);
  const p_filesz = elf.readUInt32LE(off + 16);
  const p_memsz  = elf.readUInt32LE(off + 20);
  if (p_type === PT_LOAD) {
    loads.push({ p_offset, p_vaddr, p_filesz, p_memsz });
    const end = p_vaddr + p_memsz;
    if (end > maxEnd) maxEnd = end;
  }
}

const STACK_SIZE = 32 * 1024 * 1024; // 32 MB stack
const baseTop = (maxEnd + 0xffff) & ~0xffff;
const SP_INIT = (baseTop + STACK_SIZE - 16) & ~15;
const MEM_TOP = baseTop + STACK_SIZE + 0x10000;

const mem = new ArrayBuffer(MEM_TOP);
const u8  = new Uint8Array(mem);
const u16 = new Uint16Array(mem);
const u32 = new Uint32Array(mem);
const i32 = new Int32Array(mem);

for (const s of loads) {
  for (let k = 0; k < s.p_filesz; k++) u8[s.p_vaddr + k] = elf[s.p_offset + k];
  // bss (memsz>filesz) already zero in a fresh ArrayBuffer
}

// ---------------------------------------------------------------------------
// CPU state
// ---------------------------------------------------------------------------
const reg = new Int32Array(32);
reg[29] = SP_INIT | 0;       // $sp
reg[28] = 0x0047d090 | 0;    // $gp (from .reginfo, likely unused)
reg[31] = 0;                 // $ra
let HI = 0, LO = 0;
const fgr = new Uint32Array(32); // FPU registers (o32: 32x 32-bit)
let fcc = 0;                 // FPU condition code 0

// FP reinterpretation scratch
const fbuf = new ArrayBuffer(8);
const fdv = new DataView(fbuf);
function i2f(uw) { fdv.setUint32(0, uw >>> 0, true); return fdv.getFloat32(0, true); }
function f2i(v)  { fdv.setFloat32(0, v, true); return fdv.getUint32(0, true); }
function getD(i) { fdv.setUint32(0, fgr[i], true); fdv.setUint32(4, fgr[i + 1], true); return fdv.getFloat64(0, true); }
function setD(i, v) { fdv.setFloat64(0, v, true); fgr[i] = fdv.getUint32(0, true); fgr[i + 1] = fdv.getUint32(4, true); }

// ---------------------------------------------------------------------------
// Memory helpers (little-endian; fast path aligned, fallback bytewise)
// ---------------------------------------------------------------------------
function rd32(a) {
  if ((a & 3) === 0) return i32[a >>> 2];
  return (u8[a] | (u8[a + 1] << 8) | (u8[a + 2] << 16) | (u8[a + 3] << 24)) | 0;
}
function wr32(a, v) {
  if ((a & 3) === 0) { i32[a >>> 2] = v; return; }
  u8[a] = v; u8[a + 1] = v >>> 8; u8[a + 2] = v >>> 16; u8[a + 3] = v >>> 24;
}
function rd16u(a) {
  if ((a & 1) === 0) return u16[a >>> 1];
  return u8[a] | (u8[a + 1] << 8);
}
function wr16(a, v) {
  if ((a & 1) === 0) { u16[a >>> 1] = v & 0xffff; return; }
  u8[a] = v; u8[a + 1] = v >>> 8;
}

// ---------------------------------------------------------------------------
// Syscalls (real ones issued by real_syscall6). Convention matches the guest:
//   v0 = number, a0-a3 / t0-t1 = args, return value in v0, negative = -errno.
// ---------------------------------------------------------------------------
const SYS_read = 0, SYS_write = 1, SYS_open = 2, SYS_close = 3, SYS_lseek = 8;
const SYS_fsync = 74, SYS_exit = 60, SYS_time = 201, SYS_gettimeofday = 96, SYS_nanosleep = 35;

const hostFds = new Map(); // guestFd -> { fd, pos }
let nextFd = 5;

function readCStr(addr) {
  let s = '';
  while (true) {
    const c = u8[addr++];
    if (c === 0) break;
    s += String.fromCharCode(c);
  }
  return s;
}

function doSyscall() {
  const num = reg[2] | 0;
  const a0 = reg[4] | 0, a1 = reg[5] | 0, a2 = reg[6] | 0;
  let ret = 0;
  switch (num) {
    case SYS_write: {
      const fd = a0, buf = a1 >>> 0, count = a2 >>> 0;
      if (fd === 1 || fd === 2) {
        const b = Buffer.from(mem, buf, count);
        fs.writeSync(fd, b);
        ret = count;
      } else {
        const e = hostFds.get(fd);
        if (!e) { ret = -9; break; }
        const b = Buffer.from(mem, buf, count);
        const n = fs.writeSync(e.fd, b, 0, count, e.pos);
        e.pos += n; ret = n;
      }
      break;
    }
    case SYS_open: {
      const p = readCStr(a0 >>> 0);
      const flags = a1 | 0;
      let flag = 'r';
      if (flags & 1) flag = 'w';
      if (flags & 2) flag = 'r+';
      if ((flags & 0x40)) flag = (flags & 1) ? 'w' : 'w+'; // O_CREAT
      try {
        const hfd = fs.openSync(p, flag);
        const gfd = nextFd++;
        hostFds.set(gfd, { fd: hfd, pos: 0 });
        ret = gfd;
      } catch (err) { ret = -2; }
      break;
    }
    case SYS_read: {
      const e = hostFds.get(a0);
      if (!e) { ret = -9; break; }
      const buf = a1 >>> 0, count = a2 >>> 0;
      const b = Buffer.from(mem, buf, count);
      const n = fs.readSync(e.fd, b, 0, count, e.pos);
      e.pos += n; ret = n;
      break;
    }
    case SYS_lseek: {
      const e = hostFds.get(a0);
      if (!e) { ret = -9; break; }
      const off = a1 | 0, whence = a2 | 0;
      let sz = 0;
      try { sz = fs.fstatSync(e.fd).size; } catch (x) {}
      if (whence === 0) e.pos = off;
      else if (whence === 1) e.pos += off;
      else if (whence === 2) e.pos = sz + off;
      ret = e.pos;
      break;
    }
    case SYS_close: {
      const e = hostFds.get(a0);
      if (e) { try { fs.closeSync(e.fd); } catch (x) {} hostFds.delete(a0); ret = 0; }
      else ret = -9;
      break;
    }
    case SYS_fsync: ret = 0; break;
    case SYS_time: {
      const t = Math.floor(Date.now() / 1000);
      if (a0) wr32(a0 >>> 0, t);
      ret = t;
      break;
    }
    case SYS_gettimeofday: {
      const now = Date.now();
      if (a0) { wr32(a0 >>> 0, Math.floor(now / 1000)); wr32((a0 + 4) >>> 0, (now % 1000) * 1000); }
      ret = 0;
      break;
    }
    case SYS_nanosleep: ret = 0; break;
    case SYS_exit:
      process.stdout.write('\n[vm] guest exit(' + a0 + ')\n');
      process.exit(a0 & 0xff);
    default:
      process.stderr.write('[vm] unhandled syscall ' + num + '\n');
      ret = 0;
  }
  reg[2] = ret | 0;
}

// ---------------------------------------------------------------------------
// Frame saving (hook at DG_DrawFrame entry)
// ---------------------------------------------------------------------------
const DG_DRAWFRAME = 0x4395e4;
const DG_SCREENBUFFER = 0x4b0a40; // uint32_t* DG_ScreenBuffer
const RESX = 640, RESY = 400;
let frameIndex = 0;

function saveFrame() {
  const bufPtr = u32[DG_SCREENBUFFER >>> 2] >>> 0;
  if (bufPtr === 0) return;
  const w = RESX, h = RESY;
  const imgSize = w * h * 4;
  const fileSize = 54 + imgSize;
  const out = Buffer.alloc(fileSize);
  // BMP file header (14 bytes)
  out.writeUInt16LE(0x4d42, 0);       // 'BM'
  out.writeUInt32LE(fileSize, 2);     // file size
  out.writeUInt32LE(0, 6);            // reserved
  out.writeUInt32LE(54, 10);          // pixel data offset
  // DIB header (40 bytes)
  out.writeUInt32LE(40, 14);          // header size
  out.writeInt32LE(w, 18);            // width
  out.writeInt32LE(-h, 22);           // height (negative: top-down)
  out.writeUInt16LE(1, 26);           // planes
  out.writeUInt16LE(32, 28);          // bits per pixel
  out.writeUInt32LE(0, 30);           // compression
  out.writeUInt32LE(imgSize, 34);     // image size
  out.writeUInt32LE(0, 38);
  out.writeUInt32LE(0, 42);
  out.writeUInt32LE(0, 46);
  out.writeUInt32LE(0, 50);
  // pixel data copied verbatim (as writeBMPFile does: *pixel_data++ = pixel)
  const src = Buffer.from(mem, bufPtr, imgSize);
  src.copy(out, 54, 0, imgSize);

  const numbered = path.join(FRAME_DIR, 'frame_' + String(frameIndex).padStart(4, '0') + '.bmp');
  fs.writeFileSync(numbered, out);
  if (frameIndex === 0) fs.writeFileSync(path.join(FRAME_DIR, 'frame.bmp'), out);
  process.stdout.write('[vm] saved frame ' + frameIndex + ' -> ' + numbered + '\n');
  frameIndex++;
  if (frameIndex >= MAX_FRAMES) {
    process.stdout.write('[vm] reached ' + MAX_FRAMES + ' frames, exiting\n');
    process.exit(0);
  }
}

// ---------------------------------------------------------------------------
// Main interpreter loop
// ---------------------------------------------------------------------------
let pc = e_entry >>> 0;
let npc = (pc + 4) >>> 0;

function run() {
  for (;;) {
    if (pc === DG_DRAWFRAME) {
      saveFrame();
      pc = reg[31] >>> 0;
      npc = (pc + 4) >>> 0;
      continue;
    }
    const curpc = pc;
    const inst = i32[curpc >>> 2];
    let nnpc = (npc + 4) >>> 0;

    const op = (inst >>> 26) & 0x3f;
    const rs = (inst >>> 21) & 0x1f;
    const rt = (inst >>> 16) & 0x1f;
    const rd = (inst >>> 11) & 0x1f;
    const sa = (inst >>> 6) & 0x1f;
    const funct = inst & 0x3f;
    const imm = inst & 0xffff;
    const simm = (imm << 16) >> 16;

