          case 2:  if ((inst >>> 21) & 1) { const x = reg[rt] >>> 0; reg[rd] = sa === 0 ? x : ((x >>> sa) | (x << (32 - sa))); } else reg[rd] = reg[rt] >>> sa; break; // srl/rotr
          case 3:  reg[rd] = reg[rt] >> sa; break;                 // sra
          case 4:  reg[rd] = reg[rt] << (reg[rs] & 31); break;     // sllv
          case 6:  { const sh = reg[rs] & 31; if ((inst >>> 6) & 1) { const x = reg[rt] >>> 0; reg[rd] = sh === 0 ? x : ((x >>> sh) | (x << (32 - sh))); } else reg[rd] = reg[rt] >>> sh; break; } // srlv/rotrv
          case 7:  reg[rd] = reg[rt] >> (reg[rs] & 31); break;     // srav
          case 8:  nnpc = reg[rs] >>> 0; break;                    // jr
          case 9:  reg[rd] = (curpc + 8) | 0; nnpc = reg[rs] >>> 0; break; // jalr
          case 10: if (reg[rt] === 0) reg[rd] = reg[rs]; break;    // movz
          case 11: if (reg[rt] !== 0) reg[rd] = reg[rs]; break;    // movn
          case 12: doSyscall(); break;                            // syscall
          case 13: break;                                         // break
          case 15: break;                                         // sync
          case 16: reg[rd] = HI; break;                           // mfhi
          case 17: HI = reg[rs]; break;                           // mthi
          case 18: reg[rd] = LO; break;                           // mflo
          case 19: LO = reg[rs]; break;                           // mtlo
          case 24: case 25: { // mult / multu
            const a = reg[rs], b = reg[rt];
            const x = a >>> 0, y = b >>> 0;
            const xl = x & 0xffff, xh = x >>> 16, yl = y & 0xffff, yh = y >>> 16;
            const ll = xl * yl, lh = xl * yh, hl = xh * yl, hh = xh * yh;
            const cross = (ll >>> 16) + (lh & 0xffff) + (hl & 0xffff);
            let lo = ((ll & 0xffff) | (cross << 16)) >>> 0;
            let hi = (hh + (lh >>> 16) + (hl >>> 16) + (cross >>> 16)) >>> 0;
            if (funct === 24) { // signed adjust
              if (a < 0) hi = (hi - y) >>> 0;
              if (b < 0) hi = (hi - x) >>> 0;
            }
